#!/usr/bin/env node
// Renders the privacy SQL files and the PHP patch from privacy-statements.mjs.
//
//   node ops/db/privacy-render.mjs            write the generated files
//   node ops/db/privacy-render.mjs --check    exit 1 when any generated file is stale
//
// Generated (do not edit by hand): retention-preview.sql, retention-apply.sql, erase-preview.sql,
// erase-apply.sql, erase-reapply.sql, privacy-php.patch (new files dropin/php-store/privacy.php and
// cron-privacy.php, NOT applied to the tree).
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { ERASE, ERASE_REPORT_ONLY, LEDGER, REAPPLY, RETENTION, VARS } from './privacy-statements.mjs'

const HERE = dirname(fileURLToPath(import.meta.url))
const BIG_LIMIT = 100000000
const clean = (s) => s.replace(/\s+/g, ' ').trim()
const toSql = (s) => clean(s).replace(/\{\{limit\}\}/g, String(BIG_LIMIT)).replace(/\{\{(\w+)\}\}/g, '@$1')
const title = (t) => t.replace(/\{(\w+)\}/g, '<$1>').replace(/'/g, "''")
const NOTE = '-- GENERATED by ops/db/privacy-render.mjs from ops/db/privacy-statements.mjs. Do not edit by hand.\n'

const POLICY_DEFAULTS = (names) => `set ${names.map((n) => (typeof VARS[n] === 'number' ? `@${n} = ifnull(@${n}, ${VARS[n]})` : `@${n} = ifnull(@${n}, '')`)).join(',\n    ')};`
const RET_VARS = ['orders_days', 'identity_days', 'support_days', 'returns_days', 'outbox_days', 'resets_days', 'activity_days', 'salt']
const IDENT_DERIVE = `set @p8 = right(regexp_replace(ifnull(@phone, ''), '[^0-9]', ''), 8),
    @em = lower(trim(ifnull(@email, '')));`
// A guard that stops the client (it exits on the first error): a one-row subquery that returns two rows when the
// confirmation word is wrong -> error 1242. Nothing after it runs.
const guard = (word) => `-- GUARD: stops here unless @privacy_confirm = '${word}' (it selects a subquery that returns two rows when the word is wrong: error 1242 stops the client)
select (select 1 from dual where ifnull(binary @privacy_confirm, '') <> '${word}' union all select 2 from dual where ifnull(binary @privacy_confirm, '') <> '${word}');`
const VERIFY_ID = `-- GUARD: an erasure needs at least a phone or an email
select (select 1 from dual where @p8 = '' and @em = '' union all select 2 from dual where @p8 = '' and @em = '');`

function retentionPreview() {
  let o = `${NOTE}-- RETENTION PREVIEW. READ-ONLY: it counts, it changes nothing. Run it first, every time.
--   SET @orders_days = 90, @support_days = 365, ... (any of them, before this file); the defaults below apply otherwise.
${POLICY_DEFAULTS(RET_VARS.filter((n) => n !== 'salt'))}
`
  for (const x of RETENTION) o += `\nselect '${x.id}' as rule, '${title(x.title)}' as what, (${toSql(x.preview)}) as rows_that_would_change;\n`
  o += `\n-- information only, never changed by this file:
select 'INFO-UNSENT' as rule, 'warehouse messages still unsent after 7 days (mail is not getting through; their payload is NOT blanked)' as what,
  (select count(*) from fulfilment_outbox where sent_at is null and created_at < date_sub(now(), interval 7 day)) as rows_that_would_change;
select 'INFO-OPEN-ORDERS' as rule, 'orders older than 30 days that are still pending, packed or shipped (never blanked)' as what,
  (select count(*) from orders where fulfilment_status in ('unfulfilled','packed','shipped') and created_at < date_sub(now(), interval 30 day) and payment_status <> 'failed') as rows_that_would_change;
`
  return o
}

function retentionApply() {
  let o = `${NOTE}-- RETENTION APPLY. WRITES. Run retention-preview.sql first and read it.
--   SET @privacy_confirm = 'APPLY';  SET @salt = '<the privacy salt>';   (before this file; the salt is only needed when identity_days > 0)
--   Needs UPDATE on the columns named below, DELETE on the *_password_resets tables (and admin_activity_log when
--   activity_days > 0), INSERT on privacy_runs. No runtime account has all of that: use a one-shot job.
${guard('APPLY')}
${POLICY_DEFAULTS(RET_VARS)}
`
  for (const x of RETENTION) o += `\n-- ${x.id}: ${title(x.title)}\n${toSql(x.apply)};\nset @n_${x.id.replace(/-/g, '_')} = row_count();\n`
  const affected = RETENTION.map((x) => `'${x.id}', @n_${x.id.replace(/-/g, '_')}`).join(', ')
  o += `\ninsert into privacy_runs (kind, dry_run, policy_json, affected_json)
  values ('retention', 0, json_object(${RET_VARS.filter((n) => n !== 'salt').map((n) => `'${n}', @${n}`).join(', ')}), json_object(${affected}));
select * from privacy_runs order by id desc limit 1;
`
  return o
}

function erasePreview() {
  let o = `${NOTE}-- ERASURE PREVIEW. READ-ONLY. Counts what erase-apply.sql would change for ONE person.
--   SET @phone = '<phone>', @email = '<email>';   (either or both; a phone matches on its last 8 digits)
set @phone = ifnull(@phone, ''), @email = ifnull(@email, '');
${IDENT_DERIVE}
${VERIFY_ID}
`
  for (const x of ERASE) o += `\nselect '${x.id}' as rule, '${title(x.title)}' as what, (${toSql(x.preview)}) as rows_that_would_change;\n`
  for (const x of ERASE_REPORT_ONLY) o += `\nselect '${x.id}' as rule, '${title(x.title)}' as what, (${toSql(x.count)}) as rows_NOT_changed;\n`
  return o
}

function eraseApply() {
  let o = `${NOTE}-- ERASURE APPLY. WRITES. Run erase-preview.sql for the same person first.
--   SET @privacy_confirm = 'ERASE'; SET @phone = '...', @email = '...'; SET @salt = '<the privacy salt>';
--   One transaction: all of it or none of it. The salt is required: it keys the ledger entry that lets a later restore
--   erase this person again (erase-reapply.sql). Orders that are not closed are NOT touched (see the preview).
${guard('ERASE')}
set @phone = ifnull(@phone, ''), @email = ifnull(@email, ''), @salt = ifnull(@salt, '');
${IDENT_DERIVE}
${VERIFY_ID}
-- GUARD: the ledger needs the salt
select (select 1 from dual where @salt = '' union all select 2 from dual where @salt = '');
start transaction;
`
  for (const x of ERASE) o += `\n-- ${x.id}: ${title(x.title)}\n${toSql(x.apply)};\nset @n_${x.id.replace(/-/g, '_')} = row_count();\n`
  for (const x of LEDGER) o += `\n-- ${x.id}\n${toSql(x.apply)};\n`
  const affected = ERASE.map((x) => `'${x.id}', @n_${x.id.replace(/-/g, '_')}`).join(', ')
  o += `\ninsert into privacy_runs (kind, dry_run, policy_json, affected_json) values ('erase', 0, json_object('salted', true), json_object(${affected}));
commit;
select * from privacy_runs order by id desc limit 1;
`
  return o
}

function eraseReapply() {
  let o = `${NOTE}-- RE-APPLY THE ERASURE LEDGER. WRITES. Run this after EVERY restore from a backup older than the newest erasure.
--   SET @privacy_confirm = 'REAPPLY'; SET @salt = '<the privacy salt>';
${guard('REAPPLY')}
set @salt = ifnull(@salt, '');
select (select 1 from dual where @salt = '' union all select 2 from dual where @salt = '');
start transaction;
`
  for (const x of REAPPLY) o += `\n-- ${x.id}: ${title(x.title)}\n${toSql(x.apply)};\nset @n_${x.id.replace(/-/g, '_')} = row_count();\n`
  const affected = REAPPLY.map((x) => `'${x.id}', @n_${x.id.replace(/-/g, '_')}`).join(', ')
  o += `\ninsert into privacy_runs (kind, dry_run, policy_json, affected_json) values ('reapply', 0, json_object('salted', true), json_object(${affected}));
commit;
select * from privacy_runs order by id desc limit 1;
`
  return o
}

// ---------------------------------------------------------------------------------------------- PHP
const phpStr = (s) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
function phpRule(x, extra = {}) {
  const prep = (sql, lim) => {
    const vars = []
    const text = clean(sql).replace(/\{\{limit\}\}/g, lim).replace(/\{\{(\w+)\}\}/g, (_, n) => { vars.push(n); return '?' })
    return { text, vars }
  }
  const pv = prep(x.preview || x.count || '', '0')
  const ap = x.apply ? prep(x.apply, '%LIMIT%') : null
  const lst = (a) => `[${a.map((v) => `'${v}'`).join(', ')}]`
  return `        ${phpStr(x.id)} => ['title' => ${phpStr(clean(x.title || ''))}, 'limit' => ${x.limit === false ? 'false' : 'true'},\n`
    + `            'preview' => [${phpStr(pv.text)}, ${lst(pv.vars)}],\n`
    + `            'apply' => ${ap ? `[${phpStr(ap.text)}, ${lst(ap.vars)}]` : 'null'}${extra.kind ? `, 'kind' => '${extra.kind}'` : ''}],`
}

function privacyPhp() {
  const defaults = Object.entries(VARS).map(([k, v]) => `        '${k}' => ${typeof v === 'number' ? v : "''"},`).join('\n')
  const set = (name, list, kind) => `    '${name}' => [\n${list.map((x) => phpRule(x, { kind })).join('\n')}\n    ],`
  return `<?php
// GENERATED by ops/db/privacy-render.mjs from ops/db/privacy-statements.mjs. Do not edit by hand:
// the SQL files an administrator can run and this library are the SAME statements, and the suite
// (npm run test:db-privacy) runs both on identical data.
//
// Retention and erasure of personal data. Every function defaults to PREVIEW (counts only).
// Nothing here prints or logs a name, phone or email: the result is rule ids and row counts.
declare(strict_types=1);

function privacy_defaults(): array {
    return [
${defaults}
    ];
}

/** Policy values: code defaults, then config['privacy'] (array of the same keys), then $over. Integers are clamped. */
function privacy_vars(array $cfg, array $over = []): array {
    $v = array_merge(privacy_defaults(), is_array($cfg['privacy'] ?? null) ? $cfg['privacy'] : [], $over);
    foreach (['orders_days', 'identity_days', 'support_days', 'returns_days', 'outbox_days', 'resets_days', 'activity_days'] as $k) {
        $v[$k] = max(0, min(36500, (int)($v[$k] ?? 0)));
    }
    // a retention period shorter than the returns window would blank an address before a return can be collected
    if ($v['orders_days'] < 30) $v['orders_days'] = 30;
    $v['salt'] = (string)($cfg['privacy_salt'] ?? $v['salt'] ?? '');
    $v['phone'] = (string)($v['phone'] ?? '');
    $v['email'] = (string)($v['email'] ?? '');
    $v['p8'] = substr((string)preg_replace('/\\D+/', '', $v['phone']), -8);
    $v['em'] = mb_strtolower(trim($v['email']));
    return $v;
}

function privacy_rules(string $set): array {
    static $all = [
${set('retention', RETENTION, 'update')}
${set('erase', ERASE, 'update')}
${set('report', ERASE_REPORT_ONLY.map((x) => ({ id: x.id, title: x.title, count: x.count })), 'count')}
${set('reapply', REAPPLY, 'update')}
    ];
    if (!isset($all[$set])) throw new InvalidArgumentException('unknown_rule_set');
    return $all[$set];
}

function privacy_ledger_statements(): array {
    return [
${LEDGER.map((x) => { const t = clean(x.apply); const vars = []; const text = t.replace(/\{\{(\w+)\}\}/g, (_, n) => { vars.push(n); return '?' }); return `        ${phpStr(x.id)} => [${phpStr(text)}, [${vars.map((v) => `'${v}'`).join(', ')}]],` }).join('\n')}
    ];
}

function privacy_values(array $vars, array $names): array {
    return array_map(static fn(string $n) => $vars[$n], $names);
}

/**
 * Run one rule set. Returns [rule id => rows]. $apply=false only counts.
 * Updates and deletes run in batches of $batch rows (a rule that cannot take LIMIT runs once), so a big table never
 * holds a long lock; an erasure runs inside ONE transaction.
 */
function privacy_run(PDO $db, string $set, array $vars, bool $apply, int $batch = 500): array {
    $rules = privacy_rules($set);
    $out = [];
    $tx = $apply && ($set === 'erase' || $set === 'reapply');
    if ($tx) $db->beginTransaction();
    try {
        foreach ($rules as $id => $rule) {
            [$sql, $names] = $apply && $rule['apply'] ? $rule['apply'] : $rule['preview'];
            if (!$apply || !$rule['apply']) {
                $q = $db->prepare($sql);
                $q->execute(privacy_values($vars, $names));
                $out[$id] = (int)$q->fetchColumn();
                continue;
            }
            $total = 0;
            $stmt = $db->prepare(str_replace('%LIMIT%', (string)max(1, $batch), $sql));
            do {
                $stmt->execute(privacy_values($vars, $names));
                $n = $stmt->rowCount();
                $total += $n;
            } while ($rule['limit'] && $n >= $batch);
            $out[$id] = $total;
        }
        if ($apply && $set === 'erase') {
            if ($vars['salt'] === '') throw new RuntimeException('privacy_salt_required');
            foreach (privacy_ledger_statements() as [$sql, $names]) $db->prepare($sql)->execute(privacy_values($vars, $names));
        }
        if ($apply) {
            $db->prepare('insert into privacy_runs (kind, dry_run, policy_json, affected_json) values (?, 0, ?, ?)')
               ->execute([$set === 'retention' ? 'retention' : $set, json_encode(array_intersect_key($vars, array_flip(['orders_days', 'identity_days', 'support_days', 'returns_days', 'outbox_days', 'resets_days', 'activity_days']))), json_encode($out)]);
        }
        if ($tx) $db->commit();
    } catch (Throwable $e) {
        if ($tx && $db->inTransaction()) $db->rollBack();
        throw $e;
    }
    return $out;
}
`
}

function cronPrivacyPhp() {
  return `<?php
// Retention and erasure of personal data, from the command line ONLY.
//
//   php cron-privacy.php retention                       preview: counts per rule, changes nothing
//   php cron-privacy.php retention --apply               blank/delete what the rules say (batched)
//   php cron-privacy.php erase --phone P --email E       preview for one person
//   php cron-privacy.php erase --phone P --email E --apply
//   php cron-privacy.php reapply [--apply]               after a restore from an older backup
//
// Needs config keys: 'privacy_salt' (a long random secret; required to --apply an erasure or a reapply, and for
// identity_days > 0) and optionally 'privacy' => ['orders_days' => 90, ...]. Prints rule ids and row counts, never a
// value. Over HTTP it answers 404 and does nothing.
declare(strict_types=1);
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
require __DIR__ . '/store.php';
require __DIR__ . '/privacy.php';

$args = $argv; array_shift($args);
$cmd = $args[0] ?? '';
$opts = [];
for ($i = 1; $i < count($args); $i++) {
    if ($args[$i] === '--apply') { $opts['apply'] = true; continue; }
    if (in_array($args[$i], ['--phone', '--email'], true) && isset($args[$i + 1])) { $opts[ltrim($args[$i], '-')] = $args[++$i]; continue; }
    fwrite(STDERR, "unknown argument\\n"); exit(2);
}
if (!in_array($cmd, ['retention', 'erase', 'reapply'], true)) { fwrite(STDERR, "usage: cron-privacy.php retention|erase|reapply [--apply] [--phone P] [--email E]\\n"); exit(2); }
$apply = !empty($opts['apply']);
$cfg = store_config();
$vars = privacy_vars($cfg, ['phone' => (string)($opts['phone'] ?? ''), 'email' => (string)($opts['email'] ?? '')]);
if ($cmd === 'erase' && $vars['p8'] === '' && $vars['em'] === '') { fwrite(STDERR, "erase needs --phone and/or --email\\n"); exit(2); }
if ($apply && in_array($cmd, ['erase', 'reapply'], true) && $vars['salt'] === '') { fwrite(STDERR, "privacy_salt is not configured\\n"); exit(3); }
if ($apply && $cmd === 'retention' && $vars['identity_days'] > 0 && $vars['salt'] === '') { fwrite(STDERR, "identity_days needs privacy_salt\\n"); exit(3); }
$db = store_db();
$result = ['mode' => $apply ? 'apply' : 'preview', 'rules' => privacy_run($db, $cmd, $vars, $apply)];
if ($cmd === 'erase') $result['not_changed'] = privacy_run($db, 'report', $vars, false);
echo json_encode($result, JSON_UNESCAPED_SLASHES), "\\n";
`
}

function newFilePatch(path, text) {
  const dir = mkdtempSync(join(tmpdir(), 'privpatch-'))
  try {
    mkdirSync(join(dir, 'a'), { recursive: true }); mkdirSync(join(dir, 'b', dirname(path)), { recursive: true })
    writeFileSync(join(dir, 'b', path), text)
    const r = spawnSync('git', ['diff', '--no-index', '--no-color', '--', '/dev/null', join('b', path)], { cwd: dir, encoding: 'utf8' })
    return r.stdout.replace(/^diff --git .*$/m, `diff --git a/${path} b/${path}`).replace(/b\/b\//g, 'b/').replace(/^--- .*$/m, '--- /dev/null').replace(/^\+\+\+ .*$/m, `+++ b/${path}`).replace(/^(new file mode .*)$/m, '$1')
  } finally { rmSync(dir, { recursive: true, force: true }) }
}

export function renderAll() {
  return {
    'retention-preview.sql': retentionPreview(),
    'retention-apply.sql': retentionApply(),
    'erase-preview.sql': erasePreview(),
    'erase-apply.sql': eraseApply(),
    'erase-reapply.sql': eraseReapply(),
    'privacy-php.patch': `# New files only; nothing existing is edited. Apply from the sporta-web directory:  git apply ops/db/privacy-php.patch\n# GENERATED by ops/db/privacy-render.mjs. See ops/db/DATA-PROTECTION.md section 7 for what must happen before and after applying it.\n${newFilePatch('dropin/php-store/privacy.php', privacyPhp())}${newFilePatch('dropin/php-store/cron-privacy.php', cronPrivacyPhp())}`,
  }
}

if (process.argv[1] && process.argv[1].endsWith('privacy-render.mjs')) {
  const files = renderAll()
  if (process.argv.includes('--check')) {
    let stale = 0
    for (const [f, text] of Object.entries(files)) {
      const have = existsSync(join(HERE, f)) ? readFileSync(join(HERE, f), 'utf8') : null
      if (have !== text) { console.log(`STALE ${f}`); stale++ } else console.log(`ok    ${f}`)
    }
    process.exit(stale ? 1 : 0)
  }
  for (const [f, text] of Object.entries(files)) { writeFileSync(join(HERE, f), text); console.log(`wrote ${f} (${text.length} bytes)`) }
}
